WITH VISIBLE_USER AS (
SELECT U.USER_NUMB FROM TM_USERXM U WHERE U.USER_STAT = #{userStatActive} AND NOT EXISTS ( SELECT 1 FROM TB_USBLOC B WHERE (B.USER_NUMB = #{loginUserNumb} AND B.BLOC_NUMB = U.USER_NUMB) OR (B.USER_NUMB = U.USER_NUMB AND B.BLOC_NUMB = #{loginUserNumb}) )
SELECT U.USER_NUMB FROM TM_USERXM U WHERE U.USER_NUMB = #{loginUserNumb} AND U.USER_STAT = #{userStatActive} UNION SELECT U.USER_NUMB FROM TB_FOLLOW F JOIN TM_USERXM U ON U.USER_NUMB = F.FLOW_NUMB AND U.USER_STAT = #{userStatActive} WHERE F.USER_NUMB = #{loginUserNumb} AND NOT EXISTS ( SELECT 1 FROM TB_USBLOC B WHERE (B.USER_NUMB = #{loginUserNumb} AND B.BLOC_NUMB = U.USER_NUMB) OR (B.USER_NUMB = U.USER_NUMB AND B.BLOC_NUMB = #{loginUserNumb}) )
), FEED_BASE AS ( SELECT #{targetReport} AS TAGT_TYPE , R.REPT_NUMB AS TAGT_NUMB , U.USER_NUMB , U.USER_NICK , PF.FILE_PATH AS PORF_PATH , R.PUBC_DATE AS ACTIVITY_DATE , R.REPT_NUMB , R.LANG_CODE , R.REPT_STAT , FN_GET_CODE_NAME('READ_STAT', R.REPT_STAT, NULL, #{languageCode}) AS REPT_STAT_NAME , R.REPT_GRDE , R.REPT_CNTN , B.BOOK_NUMB , B.BOOK_TITL , B.BOOK_ATHR , B.BOOK_CVIM , CAST(NULL AS CHAR(2000)) AS CONTENT_IMAGE_PATH FROM VISIBLE_USER V JOIN TM_USERXM U ON U.USER_NUMB = V.USER_NUMB JOIN TM_REPORT R ON R.USER_NUMB = U.USER_NUMB AND R.PUBC_YSNO = #{commYes} AND R.PUBC_DATE IS NOT NULL AND R.REPT_STAT != #{reportStatRead} JOIN TM_BKINFO B ON B.BOOK_NUMB = R.BOOK_NUMB LEFT JOIN TM_FILEXM PF ON PF.FILE_NUMB = U.PROF_NUMB UNION ALL SELECT #{targetProfile} , U.PROF_NUMB , U.USER_NUMB , U.USER_NICK , PF.FILE_PATH , U.PROF_DATE , NULL , NULL , NULL , NULL , NULL , NULL , NULL , NULL , NULL , NULL , PF.FILE_PATH FROM VISIBLE_USER V JOIN TM_USERXM U ON U.USER_NUMB = V.USER_NUMB AND U.PROF_NUMB IS NOT NULL AND U.PROF_DATE IS NOT NULL LEFT JOIN TM_USSETX S ON S.USER_NUMB = U.USER_NUMB JOIN TM_FILEXM PF ON PF.FILE_NUMB = U.PROF_NUMB WHERE COALESCE(S.IMFD_YSNO, #{commYes}) = #{commYes} UNION ALL SELECT #{targetBackground} , U.BGIM_NUMB , U.USER_NUMB , U.USER_NICK , PF.FILE_PATH , U.BGIM_DATE , NULL , NULL , NULL , NULL , NULL , NULL , NULL , NULL , NULL , NULL , BF.FILE_PATH FROM VISIBLE_USER V JOIN TM_USERXM U ON U.USER_NUMB = V.USER_NUMB AND U.BGIM_NUMB IS NOT NULL AND U.BGIM_DATE IS NOT NULL LEFT JOIN TM_USSETX S ON S.USER_NUMB = U.USER_NUMB JOIN TM_FILEXM BF ON BF.FILE_NUMB = U.BGIM_NUMB LEFT JOIN TM_FILEXM PF ON PF.FILE_NUMB = U.PROF_NUMB WHERE COALESCE(S.IMFD_YSNO, #{commYes}) = #{commYes} ), LIKE_COUNT AS ( SELECT L.TAGT_TYPE , L.TAGT_NUMB , COUNT(*) AS LIKE_CNT FROM TB_LIKEXX L JOIN TM_USERXM U ON U.USER_NUMB = L.USER_NUMB AND U.USER_STAT = #{userStatActive} WHERE L.TAGT_TYPE IN (#{targetReport}, #{targetProfile}, #{targetBackground}) AND NOT EXISTS ( SELECT 1 FROM TB_USBLOC B WHERE (B.USER_NUMB = #{loginUserNumb} AND B.BLOC_NUMB = L.USER_NUMB) OR (B.USER_NUMB = L.USER_NUMB AND B.BLOC_NUMB = #{loginUserNumb}) ) GROUP BY L.TAGT_TYPE, L.TAGT_NUMB ), REPLY_COUNT AS ( SELECT R.TAGT_TYPE , R.TAGT_NUMB , COUNT(*) AS REPL_CNT FROM TB_REPLXX R WHERE R.DELT_YSNO = #{commNo} AND NOT EXISTS ( SELECT 1 FROM TB_USBLOC B WHERE (B.USER_NUMB = #{loginUserNumb} AND B.BLOC_NUMB = R.USER_NUMB) OR (B.USER_NUMB = R.USER_NUMB AND B.BLOC_NUMB = #{loginUserNumb}) ) GROUP BY R.TAGT_TYPE, R.TAGT_NUMB ) SELECT /* getFeedList */ FB.* , CASE WHEN FB.USER_NUMB = #{loginUserNumb} THEN #{commYes} ELSE #{commNo} END AS ME_YSNO , COALESCE(LC.LIKE_CNT, 0) AS LIKE_CNT , CASE WHEN UL.USER_NUMB IS NULL THEN #{commNo} ELSE #{commYes} END AS LIKE_YSNO , COALESCE(RC.REPL_CNT, 0) AS REPL_CNT , CASE WHEN FB.TAGT_TYPE = #{targetReport} AND T.ORIG_HASH = SHA2(COALESCE(FB.REPT_CNTN, ''), 256) THEN #{commYes} ELSE #{commNo} END AS TRNS_CACHE_YSNO FROM FEED_BASE FB LEFT JOIN LIKE_COUNT LC ON LC.TAGT_TYPE = FB.TAGT_TYPE AND LC.TAGT_NUMB = FB.TAGT_NUMB LEFT JOIN REPLY_COUNT RC ON RC.TAGT_TYPE = FB.TAGT_TYPE AND RC.TAGT_NUMB = FB.TAGT_NUMB LEFT JOIN TB_LIKEXX UL ON UL.USER_NUMB = #{loginUserNumb} AND UL.TAGT_TYPE = FB.TAGT_TYPE AND UL.TAGT_NUMB = FB.TAGT_NUMB LEFT JOIN TB_REPTRN T ON T.REPT_NUMB = FB.REPT_NUMB AND T.LANG_CODE = #{languageCode}
FB.TAGT_TYPE = #{tagtType}
AND FB.TAGT_NUMB = #{tagtNumb}
ORDER BY FB.ACTIVITY_DATE DESC , FB.TAGT_TYPE ASC , FB.TAGT_NUMB DESC LIMIT #{pageOffset}, #{pageLimit}

mapper.delete:

DELETE /* delImageReplyLikes */ L
  FROM TB_LIKEXX L
  JOIN TB_REPLXX R
    ON R.REPL_NUMB = L.TAGT_NUMB
   AND R.TAGT_TYPE = #{tagtType}
   AND R.TAGT_NUMB = #{tagtNumb}
 WHERE L.TAGT_TYPE = #{targetReply}

DELETE /* delImageChildReplies */
  FROM TB_REPLXX
 WHERE TAGT_TYPE = #{tagtType}
   AND TAGT_NUMB = #{tagtNumb}
   AND UPER_NUMB IS NOT NULL

DELETE /* delImageParentReplies */
  FROM TB_REPLXX
 WHERE TAGT_TYPE = #{tagtType}
   AND TAGT_NUMB = #{tagtNumb}
   AND UPER_NUMB IS NULL

DELETE /* delImageLikes */
  FROM TB_LIKEXX
 WHERE TAGT_TYPE = #{tagtType}
   AND TAGT_NUMB = #{tagtNumb}
